// Validate perception request
const data = items[0].json;

if (!data.image_base64 && !data.image_url) {
  return [{ json: { error: 'Missing image (image_base64 or image_url required)', status: 'error' } }];
}

// Check frame timestamp
const ts = data.frame_timestamp_ms || Date.now();
return [{
  json: {
    image_base64: data.image_base64,
    image_url: data.image_url,
    frame_timestamp_ms: ts,
    session_id: data.session_id || 'unknown',
    device_id: data.device_id || 'unknown',
  }
}];

// Convert Google Vision API response to structured perception JSON
// Validates output against perception schema before returning

const visionData = items[0].json;
const labels = (visionData.labelAnnotations || []).map(l => ({
  name: l.description,
  score: l.score,
}));

// Localized objects from Vision API
const localizedObjs = (visionData.localizedObjectAnnotations || []).map(o => ({
  name: o.name,
  score: o.score,
  boundingPoly: o.boundingPoly,
}));

// Map Vision labels to our object types
const labelMap = {
  'person': 'person', 'people': 'person',
  'car': 'vehicle', 'cars': 'vehicle', 'truck': 'vehicle', 'bus': 'vehicle',
  'motorcycle': 'motorcycle', 'motorbike': 'motorcycle',
  'bicycle': 'bicycle', 'bike': 'bicycle',
  'pole': 'pole', 'tree': 'tree', 'building': 'wall', 'wall': 'wall',
  'stairs': 'stairs', 'bench': 'bench', 'bin': 'bin', 'trash': 'bin',
  'door': 'door', 'fence': 'fence', 'road': 'road', 'sidewalk': 'sidewalk',
  'sign': 'sign', 'traffic light': 'sign', 'animal': 'animal',
  'construction': 'construction_barrier', 'barrier': 'construction_barrier',
  'cone': 'construction_barrier',
};

// Determine position from bounding box center
function getPositionFromPoly(poly) {
  if (!poly || !poly.normalizedVertices || poly.normalizedVertices.length === 0) {
    return 'center';
  }
  const verts = poly.normalizedVertices;
  const cx = verts.reduce((s, v) => s + v.x, 0) / verts.length;
  const cy = verts.reduce((s, v) => s + v.y, 0) / verts.length;

  let h = cx < 0.33 ? 'left' : cx > 0.66 ? 'right' : 'center';
  let dist = cy < 0.33 ? '_far' : '';
  return h + dist;
}

// Rough distance estimate from vertical position (monocular — LOW confidence)
function estimateDistance(cy, confidence) {
  if (confidence < 0.3 || cy < 0.1) return null;
  const rough = 20 * (1 - cy);
  if (rough > 18) return null; // Too far to estimate
  return Math.round(rough * 10) / 10;
}

// Build objects from localized annotations (have position)
const objects = [];
const seenTypes = new Set();

for (const obj of localizedObjs) {
  const type = labelMap[obj.name.toLowerCase()] || 'unknown_obstacle';
  if (!type) continue;

  const key = type + '_' + getPositionFromPoly(obj.boundingPoly);
  if (seenTypes.has(key)) continue;
  seenTypes.add(key);

  const pos = getPositionFromPoly(obj.boundingPoly);
  const cy = obj.boundingPoly.normalizedVertices
    ? obj.boundingPoly.normalizedVertices.reduce((s, v) => s + v.y, 0) / obj.boundingPoly.normalizedVertices.length
    : 0.5;

  objects.push({
    type: type,
    position: pos,
    estimated_distance_m: estimateDistance(cy, obj.score),
    distance_confidence: Math.min(0.6, obj.score * 0.5 + 0.2),
    blocks_path: ['vehicle','motorcycle','bicycle','person','construction_barrier','pole','wall','fence','stairs','curb','pothole','unknown_obstacle'].includes(type),
    risk: obj.score > 0.8 ? 'HIGH' : (type === 'vehicle' || type === 'motorcycle' ? 'CRITICAL' : 'MEDIUM'),
  });
}

// Supplement with labels that have no spatial info
for (const [name, score] of labels) {
  const type = labelMap[name.toLowerCase()] || 'unknown_obstacle';
  if (!type || seenTypes.has(type + '_label')) continue;
  seenTypes.add(type + '_label');

  objects.push({
    type: type,
    position: 'center', // Labels have NO position info — be honest
    estimated_distance_m: null, // No distance from labels
    distance_confidence: 0.15, // Very low — no spatial data
    blocks_path: ['vehicle','motorcycle','pole','construction_barrier'].includes(type),
    risk: score > 0.8 ? 'MEDIUM' : 'LOW',
  });
}

// Limit objects
const limitedObjects = objects.slice(0, 15);

// Analyze paths
function analyzePath(objs) {
  if (objs.length === 0) return { clear: true, risk: 'LOW', confidence: 0.85 };

  const dangerValues = objs.map(o => {
    const base = {
      vehicle: 0.95, motorcycle: 0.90, bicycle: 0.70, person: 0.65,
      construction_barrier: 0.60, pole: 0.45, wall: 0.50, fence: 0.40,
      stairs: 0.55, curb: 0.30, pothole: 0.35, tree: 0.20, bench: 0.15,
      bin: 0.10, sign: 0.12, door: 0.18, animal: 0.50, unknown_obstacle: 0.40,
    }[o.type] || 0.3;

    let distMod = 0.5;
    if (o.estimated_distance_m != null) {
      if (o.estimated_distance_m < 2) distMod = 1.0;
      else if (o.estimated_distance_m < 5) distMod = 0.8;
      else if (o.estimated_distance_m < 10) distMod = 0.5;
    }
    if (o.distance_confidence < 0.5) distMod *= 0.6;
    if (o.blocks_path) base += 0.25;

    return Math.min(base * distMod, 1);
  });

  const maxDanger = Math.max(...dangerValues);
  let risk = 'LOW';
  if (maxDanger >= 0.85) risk = 'CRITICAL';
  else if (maxDanger >= 0.65) risk = 'HIGH';
  else if (maxDanger >= 0.4) risk = 'MEDIUM';

  const hasBlocker = objs.some(o => o.blocks_path);
  return {
    clear: maxDanger < 0.3 && !hasBlocker,
    risk: risk,
    confidence: Math.min(0.95, 0.5 + 0.05 * objs.length),
  };
}

const leftObj = limitedObjects.filter(o => o.position.startsWith('left'));
const centerObj = limitedObjects.filter(o => o.position.startsWith('center'));
const rightObj = limitedObjects.filter(o => o.position.startsWith('right'));

const leftPath = analyzePath(leftObj);
const centerPath = analyzePath(centerObj);
const rightPath = analyzePath(rightObj);

// Overall risk
const riskOrder = { LOW: 0, MEDIUM: 1, HIGH: 2, CRITICAL: 3 };
let overallRisk = 'LOW';
[riskOrder[centerPath.risk], riskOrder[leftPath.risk], riskOrder[rightPath.risk],
 ...objects.map(o => riskOrder[o.risk] || 0)].forEach(r => {
  if (r > riskOrder[overallRisk]) overallRisk = ['LOW','MEDIUM','HIGH','CRITICAL'][r];
});

// Scene summary
let summary;
if (limitedObjects.length > 0) {
  const types = [...new Set(limitedObjects.map(o => o.type))].slice(0, 5);
  summary = 'Detected: ' + types.join(', ');
  if (centerObj.length > 0) summary += '. Hazard ahead.';
} else {
  summary = 'Scene analyzed. No prominent obstacles detected.';
}

const processingTime = 200; // Simulated — real would measure

return [{
  json: {
    scene_summary: summary,
    objects: limitedObjects,
    left_path: leftPath,
    center_path: centerPath,
    right_path: rightPath,
    overall_risk: overallRisk,
    confidence: Math.min(0.90, 0.5 + 0.05 * limitedObjects.length),
    frame_timestamp_ms: items[0].json.frame_timestamp_ms,
    debug: {
      provider: 'google_vision',
      label_count: labels.length,
      object_count: limitedObjects.length,
      processing_time_ms: processingTime,
      model_used: 'google_vision_labels+object_localization',
    },
  }
}];
